'use strict';
// KiloMetric Driver web app. Visual design: kilometric-mobile-ui-en (prototype). Data: KiloMetric API, contract in design.md §4.
// Every string from the server is escaped with esc(): order fields can come from OCR of untrusted documents.

const LANG='en',PREVIEW_TIMEOUT_MS=45000,SLOW_HINT_MS=8000,GPS_MAX_ACCURACY_M=100,GPS_FRESH_MS=100000,FLUSH_BATCH=50,POLL_MS=30000,POINT_EVERY_MS=10000,POINT_EVERY_M=25,MAX_PLAN_POINTS=2000;
const icons={truck:'M2 5h12v12H2z M14 9h4l4 5v3h-8 M5 17a2 2 0 1 0 4 0 M16 17a2 2 0 1 0 4 0 M14 13h7',box:'m12 3 9 5v9l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v9 M7 5.8l10 5',route:'M6 5a2 2 0 1 0 0 .1 M18 19a2 2 0 1 0 0 .1 M8 5h7a4 4 0 0 1 0 8H9a3 3 0 0 0 0 6h7',history:'M3 11a9 9 0 1 1 2 7 M3 5v6h6 M12 7v5l3 2',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2',check:'m5 12 4 4L19 6',arrow:'M5 12h14 m-6-6 6 6-6 6',back:'M19 12H5 m6-6-6 6 6 6',refresh:'M20 7a8 8 0 1 0 1 8 M20 2v5h-5',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',weight:'M4 8h16l2 13H2z M9 8V5a3 3 0 0 1 6 0v3',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14 M12 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',logout:'M9 3H3v18h6 M8 12h13 m-5-5 5 5-5 5',x:'m6 6 12 12 M6 18 18 6',gps:'M12 2v4 M12 18v4 M2 12h4 M18 12h4 M12 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12 M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4',shield:'m12 2 8 3v6c0 6-8 11-8 11S4 17 4 11V5z m-4 9 3 3 5-5',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',plus:'M12 5v14 M5 12h14'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=1)=>n==null||!Number.isFinite(Number(n))?'—':new Intl.NumberFormat('en-GB',{maximumFractionDigits:d}).format(n);
const rp=n=>n==null?'—':`Rp${num(n,0)}`;
const unknown=n=>n==null?' <small>unknown</small>':'';
const duration=min=>min==null?'—':min<60?`${Math.round(min)} min`:`${Math.floor(min/60)} h ${Math.round(min%60)} min`;
const day=s=>{if(!s)return 'Date not set';const d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(s)?s+'T00:00:00':s);return Number.isNaN(d.getTime())?esc(s):d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})};
const dayTime=s=>s?new Date(s).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const minutesSince=iso=>Math.max(0,(Date.now()-Date.parse(iso))/60000);
const HAZMAT=[['none','None'],['flammable','Flammable'],['explosive','Explosive'],['other','Other']];
const RESTRICTION={height:'Height',width:'Width',length:'Length',weight:'Gross weight',axleload:'Axle load',hazmat:'Hazardous goods',bridge_limits:'Bridge limits',truck_bans:'Truck bans',time_restrictions:'Time restrictions'};
const STATUS={assigned:['Assigned','blue'],in_transit:['In transit','orange'],completed:['Completed','green'],active:['In progress','orange']};
const TOLL_SOURCE={admin_estimate:'admin estimate',google_driving_estimate:'Google driving estimate',unknown:'unknown'};
const store={get(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}},del(k){try{localStorage.removeItem(k)}catch{}}};

const S={page:'boot',selected:null,filter:'all',user:null,demoMode:false,data:null,loadError:null,
 draft:store.get('km-driver-draft',null),gps:null,gpsBusy:false,gpsError:null,
 preview:null,previewError:null,previewLoading:false,previewSlow:false,routeIndex:0,dispatcher:false,skipRoute:false,
 tripDetail:null,tracking:{watchId:null,status:'off',error:null,last:null,lastQueuedAt:0},flushing:false,wakeLock:null,pollTimer:null,permission:null,busy:false};

class ApiError extends Error{constructor(status,message,body){super(message);this.status=status;this.body=body}}
async function api(path,{method='GET',body,timeout=15000}={}){
 const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),timeout);let res;
 try{res=await fetch(path,{method,credentials:'same-origin',headers:body!==undefined?{'content-type':'application/json'}:{},body:body!==undefined?JSON.stringify(body):undefined,signal:ctrl.signal})}
 catch(e){throw new ApiError(0,e.name==='AbortError'?'The server took too long to respond. Try again.':'No connection to the server.')}
 finally{clearTimeout(timer)}
 const data=await res.json().catch(()=>({}));
 if(res.status===401&&path!=='/api/login'){signedOut('Your session ended. Please sign in again.');throw new ApiError(401,data.error||'Please sign in.',data)}
 if(!res.ok)throw new ApiError(res.status,data.error||`Request failed (HTTP ${res.status}).`,data);
 return data;
}
async function refresh(){try{S.data=await api('/api/state');S.loadError=null}catch(e){if(e.status!==401)S.loadError=e.message}render()}

const trucks=()=>S.data?.trucks||[],orders=()=>S.data?.orders||[],trips=()=>S.data?.trips||[];
const activeTrip=()=>trips().find(t=>t.status==='active')||null;
const truckById=id=>trucks().find(t=>t.id===id)||null;
const orderById=id=>orders().find(o=>o.id===id)||null;
const cpkFor=id=>S.data?.analytics?.trucks?.find(t=>t.id===id)?.cpk??null;

function go(page,id){S.page=page;if(id!==undefined)S.selected=id;closeModal();render();document.querySelector('.workspace')?.scrollTo(0,0);if(page==='historyDetail'||page==='trip')loadTripDetail()}
function signedOut(message){stopTracking();S.user=null;S.data=null;S.page='login';render();if(message)toast(message)}

const btn=(text,action,kind='primary',disabled=false,attrs='')=>`<button class="btn ${kind}" onclick="${action}" ${disabled?'disabled':''} ${attrs}>${text}</button>`;
const badge=status=>{const [label,color]=STATUS[status]||[status,'blue'];return `<span class="badge ${color}">${status==='in_transit'||status==='active'?'<span class="dot" style="background:#b45309"></span>':''}${esc(label)}</span>`};
const brand=()=>`<div class="brand"><span class="brandmark">${icon('route')}</span><div>KiloMetric<small>DRIVER APP</small></div></div>`;
const heading=(title,sub,action='')=>`<div class="pagehead"><div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;
const back=p=>`<button class="back" onclick="go('${p}')">${icon('back')} Back</button>`;
const kv=(k,v)=>`<div class="keyval"><span class="muted">${k}</span><strong>${v}</strong></div>`;
const empty=(title,sub='',action='')=>`<div class="card empty">${icon('box')}<h2>${title}</h2><p class="small">${sub}</p>${action}</div>`;
const skeleton=()=>'<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>';
const restrictions=r=>`<p class="restriction checked">Checked: ${r.checked.length?r.checked.map(k=>esc(RESTRICTION[k]||k)).join(' · '):'none'}</p><p class="restriction">Unknown: ${r.unknown.map(k=>esc(RESTRICTION[k]||k)).join(' · ')||'—'}</p>`;
const tel=c=>c?`<a class="btn flat" href="tel:${esc(c.replace(/[^\d+]/g,''))}">Call ${esc(c)} ${icon('arrow')}</a>`:'';

function nav(){const p=S.page,current=p==='detail'?'orders':['pretrip','routes','complete'].includes(p)?'trip':p==='historyDetail'?'history':p;const open=orders().filter(o=>o.status!=='completed').length;
 return [['orders','box','Orders'],['trip','route','Trip'],['history','history','History'],['account','user','Account']].map(([id,i,l])=>`<button class="${current===id?'selected':''}" onclick="go('${id}')">${icon(i)}<span>${l}</span>${id==='orders'&&open?`<span class="count">${open}</span>`:''}</button>`).join('')}
function shell(content){const pending=queue().points.length;
 return `<div class="workspace">${!navigator.onLine?'<div class="offline">You are offline. Showing the last loaded data.</div>':''}<header class="topbar">${brand()}<span>${pending?`<span class="badge orange">${pending} GPS pending</span> `:''}${S.data?.sampleData?'<span class="badge example">Sample data</span>':''}</span></header><main>${S.loadError?`<div class="banner error">${esc(S.loadError)} ${btn('Try again','refresh()','flat')}</div>`:''}${content}</main></div><nav class="bottom-nav" aria-label="Main navigation">${nav()}<div class="home-indicator" aria-hidden="true"></div></nav>`}

function loginPage(){return `<div class="login-wrap"><section class="login-story">${brand()}<div><h1>Every journey,<br>clearly recorded.</h1><p>From preparation to arrival. One place for every journey.</p></div><small style="color:#b8cfff">KiloMetric · Driver workspace</small></section><div class="login-form"><form onsubmit="event.preventDefault();signIn(this)">${brand()}<h1>KiloMetric Driver</h1><p class="muted">Sign in to view your assignments.</p>${S.demoMode?'<div class="banner" style="margin-top:24px">Demo server. Account: <b>driver@demo.id</b> · password <b>demo1234</b></div>':''}<label class="field"><span>Email</span><input name="email" type="email" autocomplete="username" autocapitalize="none" required></label><label class="field password"><span>Password</span><input id="password" name="password" type="password" autocomplete="current-password" required><button type="button" onclick="const p=document.getElementById('password');p.type=p.type==='password'?'text':'password';this.textContent=p.type==='password'?'Show':'Hide'">Show</button></label><button class="btn primary full" type="submit">Sign in ${icon('arrow')}</button><p id="login-error" class="form-error"></p><p class="footnote" style="text-align:center">Accounts are created by your admin.<br>Self-registration is not available.</p></form></div></div>`}
async function signIn(form){const submit=form.querySelector('[type=submit]'),error=document.getElementById('login-error');if(submit.disabled)return;
 submit.disabled=true;submit.innerHTML='<span class="spinner"></span> Signing in…';error.textContent='';
 try{const r=await api('/api/login',{method:'POST',body:{email:form.email.value,password:form.password.value}});S.user=r.user;if(r.user.role!=='driver'){go('notDriver');return}await refresh();const a=activeTrip();if(a)startTracking(a.id);go(a?'trip':'orders')}
 catch(e){submit.disabled=false;submit.innerHTML=`Sign in ${icon('arrow')}`;error.textContent=e.message}}
async function signOut(){try{await api('/api/logout',{method:'POST',body:{}})}catch{}store.del('km-driver-draft');S.draft=null;signedOut('Signed out.')}

function orderCard(o){const last=o.stops.at(-1);return `<article class="order-card" tabindex="0" role="button" aria-label="Order ${esc(o.reference)}" onclick="go('detail','${esc(o.id)}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();go('detail','${esc(o.id)}')}"><div class="card-top"><span class="ref">${esc(o.reference)}</span>${badge(o.status)}</div><h2 class="order-title">${esc(o.customer)||'Customer not set'}</h2><div class="timeline"><div class="stop"><span class="stop-marker"></span><div class="stop-label">PICKUP</div><strong>${esc(o.pickupAddress)}</strong></div><div class="stop"><span class="stop-marker"></span><div class="stop-label">${o.stops.length} ${o.stops.length===1?'STOP':'STOPS'} · FINAL DESTINATION</div><strong>${esc(last?.address)}</strong></div></div><div class="order-meta"><span>${icon('weight')}${num(o.cargoWeightKg)} kg${o.cargoWeightKg==null?' · unknown':''}</span><span>${icon('calendar')}${day(o.deliveryDate)}</span></div><div class="order-estimate">${o.estimate?`<span>Estimated distance <b>${num(o.estimate.distanceKm)} km</b></span><span>Estimated cost <b>${rp(o.estimate.totalCost)}</b>${o.estimate.totalCost==null?' · unknown':''}</span>`:'<span>No admin estimate yet</span>'}</div><div class="order-open">View order details ${icon('arrow')}</div></article>`}
function ordersPage(){if(!S.data)return heading('My orders','Loading…')+skeleton();
 const rank={in_transit:0,assigned:1,completed:2},list=orders().filter(o=>S.filter==='all'||o.status===S.filter).sort((a,b)=>rank[a.status]-rank[b.status]||String(a.deliveryDate).localeCompare(String(b.deliveryDate)));
 const a=activeTrip(),first=esc(String(S.user?.name||'').split(' ')[0]);
 return `<div class="greeting"><span>Hi, ${first} ${icon('user')}</span><span>${new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</span></div>${heading('My orders',`${orders().filter(o=>o.status==='assigned').length} deliveries ready for departure.`,`<button class="icon-button" aria-label="Refresh orders" onclick="refresh().then(()=>toast('Orders refreshed'))">${icon('refresh')}</button>`)}${a?`<button class="trip-resume" onclick="go('trip')"><span class="resume-icon">${icon('truck')}</span><span><b>Trip in progress</b><small>${esc(a.plate)} → ${esc(a.destination)}</small></span>${icon('arrow')}</button>`:trucks().map(t=>`<div class="truck-strip"><span class="truck-strip-icon">${icon('truck')}</span><div><b>${esc(t.plate)}</b><small>${esc(t.model)} · ${num(t.odometer,0)} km</small></div><span class="availability"><span class="dot"></span> Assigned</span></div>`).join('')}<div class="filters" aria-label="Filter orders">${[['all','All'],['assigned','Assigned'],['in_transit','In transit'],['completed','Completed']].map(([v,t])=>`<button class="${S.filter===v?'active':''}" onclick="S.filter='${v}';render()">${t}</button>`).join('')}</div><div class="sectionhead"><h2>Deliveries</h2><span class="small">${list.length} ${list.length===1?'order':'orders'}</span></div>${list.length?list.map(orderCard).join(''):empty('No orders assigned yet.','Contact your dispatcher.')}<p class="list-end">${icon('shield')} Check your truck and cargo before departure.</p>`}
function detailPage(){const o=orderById(S.selected);if(!o)return back('orders')+empty('Order not found','It may have been reassigned.');const e=o.estimate,a=activeTrip();
 const stops=`<div class="timeline"><div class="stop"><span class="stop-marker"></span><div class="stop-label">PICKUP</div><strong>${esc(o.pickupAddress)}</strong></div>${o.stops.map((s,i)=>`<div class="stop"><span class="stop-marker"></span><div class="stop-label">STOP ${i+1}${i===o.stops.length-1?' · FINAL DESTINATION':''}</div><strong>${esc(s.recipient)||'Recipient not set'}</strong><p class="small">${esc(s.address)}</p>${s.notes?`<p class="footnote">${esc(s.notes)}</p>`:''}${tel(s.contact)}</div>`).join('')}</div>`;
 const action=o.status==='assigned'?btn('Prepare this delivery',`startPretrip('${esc(o.id)}')`,'primary full',!!a)+(a?'<p class="small">Complete your active trip first.</p>':''):o.status==='in_transit'?btn('Open active trip',"go('trip')",'primary full'):btn('View trip history',o.tripId?`go('historyDetail','${esc(o.tripId)}')`:"go('history')",'primary full');
 return `<div class="flow">${back('orders')}${heading('Order details',esc(o.reference))}<div class="card"><div class="card-top"><h2>Delivery</h2>${badge(o.status)}</div><h2 style="margin-top:20px">${esc(o.customer)||'Customer not set'}</h2><p class="small">${day(o.deliveryDate)}</p>${o.notes?`<p class="footnote">${esc(o.notes)}</p>`:''}</div><div class="card"><h2 style="margin-bottom:24px">Delivery route</h2>${stops}</div><div class="card"><h2>Cargo</h2>${o.items.length?o.items.map(i=>kv(esc(i.description)||'Item',i.quantity==null?'—':`${num(i.quantity)} ${esc(i.unit)}`)).join(''):'<p class="small">No cargo lines.</p>'}<hr class="divider">${kv('Cargo weight',num(o.cargoWeightKg)+' kg'+unknown(o.cargoWeightKg))}</div><div class="card"><h2>Cost estimate (admin)</h2>${e?[['Distance',e.distanceKm==null?'—':num(e.distanceKm)+' km'],['Maintenance',rp(e.maintenanceCost)+unknown(e.maintenanceCost)],['Fuel',rp(e.fuelCost)+unknown(e.fuelCost)],['Tolls',rp(e.tollCost)+unknown(e.tollCost)],['Total',rp(e.totalCost)+unknown(e.totalCost)],['Total trip CPK',e.totalCpk==null?'—'+unknown(null):rp(e.totalCpk)+'/km']].map(([k,v])=>kv(k,v)).join('')+`<p class="footnote">Toll source: ${esc(TOLL_SOURCE[e.tollSource]||'unknown')}<br>Not an invoice; calculated from historical truck CPK.</p>`:'<p class="small">No estimate from the admin yet.</p>'}</div><div class="sticky-action">${action}</div></div>`}

// Dimensions and weights are truck master data set by the admin; the driver declares only cargo and hazardous goods.
function defaultSpecs(truck,order){return {loadKg:order?.cargoWeightKg??null,hazmat:'none'}}
const master=()=>truckById(S.draft?.truckId)?.specifications||null;
const sentSpecs=d=>({loadKg:d.specs.loadKg,hazmat:d.specs.hazmat||'none'});
const MASTER_FIELDS=[['heightM','Height','m'],['widthM','Width','m'],['lengthM','Length','m'],['axles','Number of axles',''],['tareKg','Tare weight','kg'],['maxGrossKg','Maximum weight','kg']];
function specsCard(){const m=master();return `<div class="card"><div class="card-top"><h2>Truck specifications</h2><span class="small">Set by your admin</span></div>${m?`<div style="margin-top:14px">${MASTER_FIELDS.map(([k,l,u])=>kv(l,`${num(m[k])}${u?' '+u:''}`)).join('')}</div><p class="footnote">Check that the truck matches. If it does not, tell your admin before departure.</p>`:'<div class="banner warning" style="margin-top:14px">Truck specifications are not set by your admin yet. Height, width, length and weight limits will not be checked on route options.</div>'}</div>`}
function startPretrip(orderId){if(activeTrip()){toast('Complete your active trip first.');return}const order=orderId?orderById(orderId):null,truck=order?truckById(order.truckId):trucks()[0];
 if(!S.draft||S.draft.orderId!==(orderId||null))S.draft={orderId:orderId||null,truckId:truck?.id||null,startOdometer:truck?.odometer??null,specs:defaultSpecs(truck,order),confirmed:false,destinations:['']};
 S.gps=null;S.gpsError=null;saveDraft();go('pretrip')}
function saveDraft(){store.set('km-driver-draft',S.draft)}
function selectTruck(id){const t=truckById(id);S.draft.truckId=id;S.draft.startOdometer=t?.odometer??null;S.draft.specs={...defaultSpecs(t,null),loadKg:S.draft.specs.loadKg,hazmat:S.draft.specs.hazmat};saveDraft();render()}
const FIELD_LABEL={startOdometer:'Starting odometer',loadKg:'Cargo weight'};
const RANGES={startOdometer:[0,1e12,1],loadKg:[0,200000,1]};
function draftValue(key){return key==='startOdometer'?S.draft.startOdometer:S.draft.specs[key]}
function minFor(key){const t=truckById(S.draft.truckId),o=orderById(S.draft.orderId);return key==='startOdometer'?t?.odometer??0:key==='loadKg'?o?.cargoWeightKg??0:RANGES[key][0]}
function field(label,key){const [,max,step]=RANGES[key],min=minFor(key);return `<label class="field"><span>${label}</span><input type="number" inputmode="decimal" value="${esc(draftValue(key))}" min="${min}" max="${max}" step="${step}" required oninput="setDraft('${key}',this.value)"><small>${key==='startOdometer'?`Minimum ${num(min,0)} km`:key==='loadKg'&&min>0?`Minimum ${num(min,0)} kg as specified in the order`:`${num(min)}–${num(max)}`}</small></label>`}
function setDraft(key,value){const v=value===''?null:Number(value);if(key==='startOdometer')S.draft.startOdometer=v;else S.draft.specs[key]=v;saveDraft();updatePretrip()}
function pretripProblems(){const d=S.draft,problems=[];if(!d)return['No draft'];if(!truckById(d.truckId))problems.push('Select an assigned truck.');
 for(const k of Object.keys(RANGES)){const v=draftValue(k),min=minFor(k),max=RANGES[k][1];if(v==null||!Number.isFinite(v)||v<min||v>max)problems.push(`${FIELD_LABEL[k]} must be between ${num(min)} and ${num(max)}.`)}
 const m=master();if(m&&d.specs.loadKg!=null&&m.tareKg+d.specs.loadKg>m.maxGrossKg)problems.push('Gross weight exceeds the maximum.');
 if(!d.orderId&&!d.destinations.some(x=>x.trim()))problems.push('Enter a destination.');
 if(!d.confirmed)problems.push('Confirm your declaration.');if(!gpsFresh())problems.push('Capture your GPS location.');return problems}
function updatePretrip(){const d=S.draft,el=document.getElementById('gross');if(el&&d){const m=master();if(!m||d.specs.loadKg==null){el.innerHTML=m?'Enter the cargo weight to see the gross weight.':'Gross weight unknown: truck specifications are not set.';el.className='banner'}else{const gross=m.tareKg+d.specs.loadKg,over=gross>m.maxGrossKg;el.innerHTML=`Gross weight = <b>${num(gross,0)} kg</b> out of a maximum of ${num(m.maxGrossKg,0)} kg${over?'<br>Over the limit; the server will reject this load.':''}`;el.className='banner'+(over?' error':'')}}
 const ok=!pretripProblems().length;document.querySelectorAll('[data-continue]').forEach(b=>b.disabled=!ok);const hint=document.getElementById('pretrip-hint');if(hint)hint.textContent=ok?'':pretripProblems()[0]}
function gpsLine(){return S.gpsBusy?'Getting your location…':S.gps?`Location ready · ${S.gps.latitude.toFixed(5)}, ${S.gps.longitude.toFixed(5)} · accuracy ${num(S.gps.accuracy,0)} m · ${Math.round((Date.now()-S.gps.timestamp)/1000)} s ago`:S.gpsError?esc(S.gpsError):'Not captured yet'}
function pretripPage(){const d=S.draft;if(!d)return back('trip')+empty('Nothing to prepare','Choose an order first.',btn('Open orders',"go('orders')"));const o=orderById(d.orderId),t=truckById(d.truckId);
 if(!trucks().length)return back('trip')+empty('No truck assigned','Contact your admin.');
 return `<div class="flow">${back(o?'detail':'trip')}${heading('Pre-trip checks','Review your details before departure.')}<div class="stepbar"><b>01 Prepare</b><i></i><span>02 Route</span><i></i><span>03 Start</span></div>${o?`<div class="banner">${esc(o.reference)} · ${esc(o.customer)}<br><b>${esc(o.stops.at(-1).address)}</b> · ${num(o.cargoWeightKg,0)} kg${unknown(o.cargoWeightKg)}</div>`:''}<div class="card"><h2>Truck</h2><label class="field" style="margin-top:18px"><span>Assigned truck</span><select ${o?'disabled':''} onchange="selectTruck(this.value)">${trucks().map(x=>`<option value="${esc(x.id)}" ${x.id===d.truckId?'selected':''}>${esc(x.plate)} · ${esc(x.model)}</option>`).join('')}</select><small>${o?'Truck is assigned by the order':'Trucks assigned to you'}</small></label>${kv('Odometer on record',num(t?.odometer,0)+' km')}${kv('Maintenance CPK',cpkFor(d.truckId)==null?'—'+unknown(null):rp(cpkFor(d.truckId))+'/km')}${field('Starting odometer (km)','startOdometer')}</div>${specsCard()}<div class="card"><h2 style="margin-bottom:20px">Cargo</h2>${field('Cargo weight (kg)','loadKg')}<label class="field"><span>Hazardous cargo</span><select onchange="S.draft.specs.hazmat=this.value;saveDraft()">${HAZMAT.map(([v,l])=>`<option value="${v}" ${d.specs.hazmat===v?'selected':''}>${l}</option>`).join('')}</select></label><div id="gross" class="banner"></div></div>${o?'':`<div class="card"><h2>Destinations</h2>${d.destinations.map((x,i)=>`<div class="dest-row"><label class="field"><span>Stop ${i+1}${i===d.destinations.length-1?' · final':''}</span><input value="${esc(x)}" maxlength="300" placeholder="Place name and city, e.g. Kawasan Industri Pulogadung, Jakarta" oninput="S.draft.destinations[${i}]=this.value;saveDraft();updatePretrip()"></label>${d.destinations.length>1?`<button class="icon-button" aria-label="Remove stop" onclick="S.draft.destinations.splice(${i},1);saveDraft();render()">${icon('x')}</button>`:''}</div>`).join('')}${d.destinations.length<10?btn(icon('plus')+' Add stop',"S.draft.destinations.push('');saveDraft();render()",'flat'):''}<p class="footnote">Named places (industrial estates, ports, warehouses) are found more precisely than street addresses.</p></div>`}<div class="card"><h2>Starting location</h2><p class="footnote">Your phone location is the trip origin. Accuracy must be ${GPS_MAX_ACCURACY_M} m or better.</p><div style="margin-top:16px">${btn(icon('gps')+' Get GPS location',"captureGps()",'',S.gpsBusy)}</div><p id="gps-status" class="small">${gpsLine()}</p></div><label class="check"><input type="checkbox" ${d.confirmed?'checked':''} onchange="S.draft.confirmed=this.checked;saveDraft();updatePretrip()"><span>I checked that the truck matches the specifications above, and the cargo details are correct for this departure.</span></label><div class="sticky-action"><p id="pretrip-hint" class="small"></p><button class="btn primary full" data-continue onclick="loadRoutes()" disabled>View route options ${icon('arrow')}</button><button class="btn flat full" data-continue onclick="S.skipRoute=true;S.dispatcher=false;showStart()" disabled>Skip routes and start</button></div></div>`}

const toPoint=p=>({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:Math.round(p.coords.accuracy*10)/10,timestamp:Math.round(p.timestamp)});
const gpsFresh=()=>S.gps&&Date.now()-S.gps.timestamp<GPS_FRESH_MS;
function gpsMessage(err){return err.code===1?'Location permission denied. Allow location for this site in your browser settings, then try again.':err.code===3?'Getting a location timed out. Move to an open area and try again.':'Location is unavailable on this device.'}
function getPosition(){return new Promise((resolve,reject)=>{
 if(!('geolocation' in navigator))return reject(new Error('This browser has no location support.'));
 if(!window.isSecureContext)return reject(new Error('Location needs HTTPS. Open the app through an https:// address (or localhost).'));
 navigator.geolocation.getCurrentPosition(p=>{const pt=toPoint(p);pt.accuracy>GPS_MAX_ACCURACY_M?reject(new Error(`Accuracy ${num(pt.accuracy,0)} m; ${GPS_MAX_ACCURACY_M} m or better is required. Move to an open area and try again.`)):resolve(pt)},e=>reject(new Error(gpsMessage(e))),{enableHighAccuracy:true,timeout:20000,maximumAge:0})})}
async function captureGps(){S.gpsBusy=true;S.gpsError=null;renderGps();try{S.gps=await getPosition();toast('Location captured')}catch(e){S.gps=null;S.gpsError=e.message}S.gpsBusy=false;if(S.page==='pretrip')render()}
function renderGps(){const el=document.getElementById('gps-status');if(el)el.textContent=gpsLine()}
async function freshGps(){if(gpsFresh())return S.gps;S.gps=await getPosition();return S.gps}

function draftStops(){return S.draft.destinations.map(x=>x.trim()).filter(Boolean).map(address=>({address}))}
async function loadRoutes(){if(pretripProblems().length)return;S.skipRoute=false;S.dispatcher=false;S.routeIndex=0;S.preview=null;S.previewError=null;S.previewLoading=true;S.previewSlow=false;go('routes');
 const slow=setTimeout(()=>{S.previewSlow=true;if(S.page==='routes')render()},SLOW_HINT_MS);
 try{const origin=await freshGps(),d=S.draft;S.preview=await api('/api/routes/preview',{method:'POST',timeout:PREVIEW_TIMEOUT_MS,body:{origin,specs:sentSpecs(d),lang:LANG,...(d.orderId?{orderId:d.orderId}:{stops:draftStops(),truckId:d.truckId})}});
  const rec=S.preview.routes.findIndex(r=>r.recommended);S.routeIndex=rec>=0?rec:0}
 catch(e){S.previewError={status:e.status,message:e.message,stops:e.body?.stops||null}}
 finally{clearTimeout(slow);S.previewLoading=false;if(S.page==='routes')render()}}
const selectedRoute=()=>S.preview?.routes?.[S.routeIndex]||null;
function foundCard(stops){if(!stops?.length)return '';return `<div class="card"><h2>Locations found</h2><p class="footnote" style="margin-bottom:12px">Check that each place is the one you expect. The map provider sometimes picks a different place.</p><div class="found">${stops.map((s,i)=>`<div class="found-row"><p class="small">${i===0&&S.draft?.orderId?'Pickup':`Stop ${S.draft?.orderId?i:i+1}`} · ${esc(s.address)}</p>${s.latitude==null?'<strong>Not found</strong><span class="chip bad">Not found</span>':`<strong>Found as: ${esc(s.geocodeLabel)||'unnamed point'}</strong>${s.geocodePrecision==='approximate'?'<span class="chip warn">Approximate</span><p class="small">Only the general area was found; distance and time to this stop are approximate.</p>':s.geocodePrecision==='exact'?'<span class="chip ok">Exact place</span>':''}`}</div>`).join('')}</div></div>`}
function routesPage(){const p=S.preview,e=S.previewError,head=`<div class="flow">${back('pretrip')}${heading('Choose a route','Fastest route priority · Tolls allowed')}<div class="stepbar"><span>01 Prepare</span><i></i><b>02 Route</b><i></i><span>03 Start</span></div>`;
 if(S.previewLoading)return head+`<div class="map-placeholder"><div class="map-grid"></div><div class="map-message">${icon('route')}<div><b>${S.previewSlow?'Still calculating… the free routing provider can be slow.':'Calculating routes for your truck…'}</b></div></div></div>${skeleton()}</div>`;
 const startless=`<label class="check"><input type="checkbox" ${S.dispatcher?'checked':''} onchange="S.dispatcher=this.checked"><span>This route has been approved by the dispatcher (external planning).</span></label>`;
 if(e)return head+(e.status===422?`<div class="banner error">${esc(e.message)}</div>${foundCard(e.stops)}`:`<div class="banner error">${esc(e.message)}</div>`)+`<div class="sticky-action">${e.status!==422&&e.status!==400?btn('Try again','loadRoutes()','primary full'):''}${e.status===400?btn('Back to pre-trip checks',"go('pretrip')",'primary full'):btn('Start without a route',"S.skipRoute=true;S.dispatcher=false;showStart()",'full')}</div></div>`;
 if(!p)return head+empty('No routes yet','',btn('Calculate routes','loadRoutes()'))+'</div>';
 const routes=p.routes,shared=routes.length?routes[0].warnings.filter(w=>routes.every(r=>r.warnings.includes(w))):[],single=routes.length===1,x=p.explanation;
 const card=(r,i)=>{const chosen=i===S.routeIndex,own=r.warnings.filter(w=>!shared.includes(w)),ai=x?.status==='ok'?x.perRoute.find(q=>q.routeId===r.id):null;
  return `<article class="card routecard ${chosen?'chosen':''}" ${single?'':`role="radio" aria-checked="${chosen}" tabindex="0" onclick="pickRoute(${i})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();pickRoute(${i})}"`}><div class="card-top"><h2>${single?'':chosen?'◉ &nbsp; ':'○ &nbsp; '}Route ${r.rank}</h2><div>${r.rank===1&&!single?'<span class="badge blue">Fastest</span>':''}${r.recommended?` <span class="badge green">${{cost:'Recommended · lowest cost',time:'Recommended · fastest'}[S.preview.recommendation?.basis]??'Only route'}</span>`:''}</div></div><div class="route-numbers">${num(r.distanceKm)} <small>km</small> <span style="color:#cad2df;font-weight:400">/</span> ${duration(r.durationMin)}</div><p class="small">Ascent ↑ ${num(r.ascendM,0)} m · Descent ↓ ${num(r.descendM,0)} m${r.ascendM==null?' · unknown':''}</p><p class="small">${r.tollIdr==null?'Tolls: unknown':r.tollIdr===0?'No toll roads':`Toll ${rp(r.tollIdr)} (Google Maps)`}${r.trafficDurationMin!=null?` · With current traffic ≈ ${duration(r.trafficDurationMin)}`:''}</p>${restrictions(r.restrictions)}${own.map(w=>`<p class="footnote">⚠ ${esc(w)}</p>`).join('')}${ai?`<hr class="divider"><div class="route-ai"><span class="small">AI explanation</span><em>${esc(ai.headline)}</em><ul class="ai">${ai.pros.map(t=>`<li class="pro">${esc(t)}</li>`).join('')}${ai.cons.map(t=>`<li class="con">${esc(t)}</li>`).join('')}</ul></div>`:''}</article>`};
 return head+`${mapSlot(260)}${p.routing.provider==='fixture'?'<div class="banner warning">Sample routes: the routing provider is unavailable. Distances and times are not real.</div>':''}${shared.map(w=>`<div class="banner">${esc(w)}</div>`).join('')}${p.routing.provider==='ors'?foundCard(p.stops):''}${routes.map(card).join('')}<div class="card ai"><h3>${icon('spark')} AI explanation</h3>${x?.status==='ok'?`<p class="small">${esc(x.summary)}</p>${x.caveats.length?`<p class="footnote">${x.caveats.map(c=>`⚠ ${esc(c)}`).join('<br>')}</p>`:''}`:`<p class="small">${esc(x?.summary||'AI explanation unavailable.')}</p><p class="footnote">Route figures above still come from the routing provider.</p>`}<p class="footnote">Bridge limits, truck bans and time restrictions are not checked. Follow dispatcher guidance and posted road signs.</p></div>${startless}<div class="sticky-action">${btn(single?'Start trip with this route':`Start trip with Route ${routes[S.routeIndex]?.rank??1}`,'showStart()','primary full')}</div></div>`}
function pickRoute(i){S.routeIndex=i;render()}
// Server keeps at most 5000 plan points; stitched long routes exceed that. Keep shape with evenly spaced points.
function thin(line,max=MAX_PLAN_POINTS){if(line.length<=max)return line;const step=(line.length-1)/(max-1);return Array.from({length:max},(_,i)=>line[Math.round(i*step)])}

function destination(){const o=orderById(S.draft.orderId);return o?o.stops.at(-1).address:draftStops().at(-1)?.address||''}
function showStart(){if(pretripProblems().length){toast(pretripProblems()[0]);return}const d=S.draft,t=truckById(d.truckId),r=S.skipRoute?null:selectedRoute(),m=master(),approx=!S.skipRoute&&S.preview?.stops?.some(s=>s.geocodePrecision==='approximate');
 modal(`<h2>Start this trip?</h2><p class="small">Review your departure details.</p>${kv('Truck',esc(t?.plate))}${kv('Destination',esc(destination()))}${kv('Starting odometer',num(d.startOdometer,0)+' km')}${kv('Gross / maximum weight',m?`${num(m.tareKg+d.specs.loadKg,0)} / ${num(m.maxGrossKg,0)} kg`:'Unknown (truck specifications not set)')}${kv('Route',r?`${num(r.distanceKm)} km · ${duration(r.durationMin)}`:'No planned route')}${kv('Provider',r?(S.preview.routing.provider==='fixture'?'sample routes':'OpenRouteService'):'—')}${approx?'<div class="banner warning">Some destinations are only approximate.</div>':''}<label class="check"><input type="checkbox" ${S.dispatcher?'checked':''} onchange="S.dispatcher=this.checked;document.getElementById('confirm-start').disabled=!this.checked"><span>This route has been approved by the dispatcher (external planning).</span></label><button id="confirm-start" class="btn primary full" ${S.dispatcher?'':'disabled'} onclick="beginTrip(this)">Yes, start trip</button><p id="start-error" class="form-error"></p>${btn('Back','closeModal()','full')}`)}
async function beginTrip(button){if(!S.dispatcher||S.busy)return;S.busy=true;button.disabled=true;button.innerHTML='<span class="spinner"></span> Starting…';
 try{const d=S.draft,origin=await freshGps(),r=S.skipRoute?null:selectedRoute(),x=S.preview?.explanation;
  const routePlan=r?{routeId:r.id,provider:S.preview.routing.provider,distanceKm:r.distanceKm,durationMin:Math.max(1,r.durationMin),polyline:thin(r.polyline),restrictions:r.restrictions,explanation:x?.status==='ok'?{recommendedRouteId:x.recommendedRouteId,headline:(x.perRoute.find(q=>q.routeId===r.id)?.headline||x.summary).slice(0,200)}:null,wasRecommended:r.recommended===true,chosenAt:new Date().toISOString()}:undefined;
  const res=await api('/api/trips',{method:'POST',body:{truckId:d.truckId,...(d.orderId?{orderId:d.orderId}:{}),destination:destination(),startOdometer:d.startOdometer,specs:sentSpecs(d),specsConfirmed:true,externalRouteConfirmed:true,origin,...(routePlan?{routePlan}:{})}});
  S.busy=false;S.draft=null;store.del('km-driver-draft');S.preview=null;await refresh();startTracking(res.tripId);go('trip');toast('Trip started')}
 catch(e){S.busy=false;button.disabled=false;button.textContent='Yes, start trip';const el=document.getElementById('start-error');if(el)el.textContent=e.message}}

function queue(){return store.get('km-driver-queue',{tripId:null,points:[]})}
function pushPoint(tripId,pt){const q=queue();if(q.tripId!==tripId){q.tripId=tripId;q.points=[]}const last=q.points.at(-1);if(last&&pt.timestamp<=last.timestamp)return;q.points.push(pt);if(q.points.length>2000)q.points=q.points.slice(-2000);store.set('km-driver-queue',q)}
async function flush(timeoutMs){if(S.flushing||!navigator.onLine)return;S.flushing=true;const until=timeoutMs?Date.now()+timeoutMs:Infinity;
 try{for(let q=queue();q.tripId&&q.points.length&&Date.now()<until;q=queue()){const batch=q.points.slice(0,FLUSH_BATCH);
  try{await api(`/api/trips/${encodeURIComponent(q.tripId)}/locations`,{method:'POST',body:{points:batch}})}
  catch(e){if(e.status===400){console.warn('GPS batch rejected and dropped:',e.message)}else break}
  const now=queue();now.points=now.points.filter(p=>!batch.some(b=>b.timestamp===p.timestamp));store.set('km-driver-queue',now)}}
 finally{S.flushing=false;if(S.page==='trip')render()}}
function haversineM(a,b){const r=x=>x*Math.PI/180,dLat=r(b.latitude-a.latitude),dLon=r(b.longitude-a.longitude),h=Math.sin(dLat/2)**2+Math.cos(r(a.latitude))*Math.cos(r(b.latitude))*Math.sin(dLon/2)**2;return 12742000*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function startTracking(tripId){if(S.tracking.watchId!==null||!('geolocation' in navigator))return;store.set('km-driver-active',tripId);
 S.tracking.watchId=navigator.geolocation.watchPosition(p=>{const pt=toPoint(p),t=S.tracking;t.status='on';t.error=null;t.last=pt;
  // Sparse points keep GPS jitter from looking like impossible speed (server rejects > 160 km/h between points).
  if(pt.accuracy<=GPS_MAX_ACCURACY_M&&(!t.queued||pt.timestamp-t.queued.timestamp>=POINT_EVERY_MS||haversineM(t.queued,pt)>=POINT_EVERY_M)){t.queued=pt;pushPoint(tripId,pt);flush()}
  if(S.page==='trip')render()},
  err=>{S.tracking.status='off';S.tracking.error=gpsMessage(err);if(err.code===1)stopWatch();if(S.page==='trip')render()},{enableHighAccuracy:true,maximumAge:5000,timeout:30000});
 S.tracking.status='starting';keepAwake();clearInterval(S.pollTimer);S.pollTimer=setInterval(()=>{if(S.page==='trip'||S.page==='historyDetail')loadTripDetail()},POLL_MS)}
function stopWatch(){if(S.tracking.watchId!==null)navigator.geolocation.clearWatch(S.tracking.watchId);S.tracking.watchId=null}
function stopTracking(){stopWatch();S.tracking.status='off';clearInterval(S.pollTimer);S.pollTimer=null;store.del('km-driver-active');S.wakeLock?.release?.().catch(()=>{});S.wakeLock=null}
function resumeTracking(){const a=activeTrip();if(!a)return;stopWatch();startTracking(a.id);render()}
// Browsers stop GPS when the screen locks; keep the screen on while a trip is active.
async function keepAwake(){try{if('wakeLock' in navigator&&document.visibilityState==='visible'&&!S.wakeLock){S.wakeLock=await navigator.wakeLock.request('screen');S.wakeLock.addEventListener('release',()=>{S.wakeLock=null})}}catch{S.wakeLock=null}}
async function loadTripDetail(){const id=S.page==='trip'?activeTrip()?.id:S.selected;if(!id)return;try{const r=await api(`/api/trips/${encodeURIComponent(id)}`);S.tripDetail=r.trip;if((S.page==='trip'&&activeTrip()?.id===id)||(S.page==='historyDetail'&&S.selected===id))render()}catch{}}

function tripPage(){if(!S.data)return heading('Trip','Loading…')+skeleton();const a=activeTrip();
 if(!a)return `${heading('Trip','Every trip, clearly recorded.')}${empty('No active trip','Select an order to prepare your next trip.',btn('Start from an order',"go('orders')"))}<div style="text-align:center">${btn('Start without an order',"startPretrip(null)",'')}</div>`;
 const d=S.tripDetail?.id===a.id?S.tripDetail:null,t=S.tracking,plan=a.routing?.plan,pending=queue().points.length,stops=inStopOrder(a.deliveryStops||[],plan?.stopOrder);
 const status=t.status==='on'?`<span class="tracking on"><span class="dot"></span>GPS active · last fix ${t.last?Math.round((Date.now()-t.last.timestamp)/1000)+' s ago':'—'}</span>`:`<span class="tracking off"><span class="dot"></span>${t.status==='starting'?'Starting GPS…':esc(t.error||'GPS stopped')}</span>`;
 return `<div class="flow">${heading('Active trip','Stay focused. Arrive safely.')}${plan?.provider==='fixture'?'<div class="banner warning">Sample route: the routing provider was unavailable at departure.</div>':''}${mapSlot(280)}<div class="card"><div class="card-top"><h2>${esc(a.plate)}</h2>${badge('active')}</div><p class="muted">${esc(a.destination)}</p><div class="stats" style="margin:24px 0 0"><div><small>GPS distance (approx.)</small><h1>${num(d?.gpsDistanceKm??a.gpsDistanceKm)}</h1><small>km</small></div><div><small>Points received</small><h1>${num(d?d.points.length:a.pointCount,0)}</h1><small>by server</small></div><div><small>Duration</small><h1>${duration(minutesSince(a.startedAt))}</h1><small>since start</small></div></div><hr class="divider">${status}${t.status!=='on'&&t.status!=='starting'?btn('Resume GPS','resumeTracking()','flat'):''}${pending?`<p class="small">${pending} GPS points waiting for a connection.</p>`:''}<p class="footnote">Keep this page open with the screen on. A browser stops GPS when the screen locks or you switch apps.${S.wakeLock?' Screen is being kept on.':''}</p>${plan?`<hr class="divider"><p class="small">Planned route: ${num(plan.distanceKm)} km · ${duration(plan.durationMin)}${plan.wasRecommended?' · recommended':''}</p>${restrictions(plan.restrictions)}`:''}</div>${stops.length?`<div class="card"><h2 style="margin-bottom:20px">Delivery stops</h2><div class="timeline">${stops.map((s,i)=>`<div class="stop"><span class="stop-marker"></span><div class="stop-label">STOP ${i+1}${i===stops.length-1?' · FINAL DESTINATION':''}</div><strong>${esc(s.recipient)||'Recipient'}</strong><p class="small">${esc(s.address)}</p>${tel(s.contact)}</div>`).join('')}</div></div>`:''}${mapsLinks(a).map((u,i,all)=>`<a class="btn full" style="margin-bottom:16px" target="_blank" rel="noopener" href="${u}">${icon('map')} Open in Google Maps${all.length>1?` (part ${i+1} of ${all.length})`:''}</a>`).join('')}<p class="footnote" style="margin-bottom:16px">Official distance comes from the arrival odometer, not GPS.</p><div class="sticky-action">${btn('Arrived at destination',"go('complete')",'primary full')}</div></div>`}

// Same as the Android app: delivery stops in the routed order, and every planned stop sent to Google Maps in that order.
// A Google Maps link takes at most 9 waypoints + 1 destination, so longer plans are split into two links.
function inStopOrder(items,order){return Array.isArray(order)&&order.length===items.length&&order.every((v,i)=>order.indexOf(v)===i&&v>=0&&v<items.length)?order.map(i=>items[i]):items}
function mapsLinks(a){
 const pts=(a.routing?.plan?.stops||[]).filter(p=>Number.isFinite(p?.latitude)&&Number.isFinite(p?.longitude));
 if(!pts.length)return [`https://www.google.com/maps/dir/?api=1&travelmode=driving&destination=${encodeURIComponent(a.destination)}`];
 const at=p=>`${p.latitude},${p.longitude}`,url=list=>`https://www.google.com/maps/dir/?api=1&travelmode=driving&destination=${at(list.at(-1))}${list.length>1?`&waypoints=${list.slice(0,-1).map(at).join('%7C')}`:''}`;
 return pts.length>10?[url(pts.slice(0,10)),url(pts.slice(10))]:[url(pts)];
}
function completeMin(a){return Math.max(a.startOdometer,truckById(a.truckId)?.odometer??0)}
function completePage(){const a=activeTrip();if(!a)return tripPage();const min=completeMin(a);
 return `<div class="flow">${back('trip')}${heading('Complete trip','Enter your odometer reading on arrival.')}<div class="card"><h2>${esc(a.plate)}</h2><p class="muted">${esc(a.destination)}</p>${kv('Starting odometer',num(a.startOdometer,0)+' km')}${kv('GPS distance (approx.)',num(a.gpsDistanceKm)+' km')}${kv('Duration',duration(minutesSince(a.startedAt)))}</div><div class="card"><label class="field"><span>Arrival odometer (km)</span><input class="mono" style="height:72px;font-size:32px" id="endodo" type="number" inputmode="numeric" min="${min}" placeholder="${min}" oninput="updateComplete()"><small>Minimum ${num(min,0)} km</small></label><div id="complete-preview" class="banner">Enter the arrival odometer reading.</div><p class="footnote">Estimate shown for preview only; official figures come from the server after saving.<br>Not an invoice; calculated from historical truck CPK at departure.</p></div><div class="sticky-action"><button id="complete-button" class="btn primary full" onclick="confirmComplete()" disabled>Complete trip</button></div></div>`}
function updateComplete(){const a=activeTrip(),input=document.getElementById('endodo'),n=Number(input.value),valid=input.value!==''&&Number.isFinite(n)&&n>=completeMin(a);document.getElementById('complete-button').disabled=!valid;
 document.getElementById('complete-preview').innerHTML=valid?`Odometer distance = <b>${num(n-a.startOdometer)} km</b><br>${a.maintenanceCpkAtStart==null?'Maintenance estimate unavailable (truck CPK unknown at departure).':`Estimated maintenance cost ≈ ${rp((n-a.startOdometer)*a.maintenanceCpkAtStart)}`}`:'The reading must not be below the minimum.'}
function confirmComplete(){const a=activeTrip(),n=Number(document.getElementById('endodo').value);if(!(n>=completeMin(a)))return;
 modal(`<h2>Complete trip?</h2><p class="small">The trip will be closed and the truck odometer updated. This cannot be undone.</p>${kv('Truck',esc(a.plate))}${kv('Arrival odometer',num(n,0)+' km')}${kv('Odometer distance',num(n-a.startOdometer)+' km')}<button class="btn primary full" onclick="finishTrip(${n},this)">Yes, complete trip</button><p id="complete-error" class="form-error"></p>${btn('Back','closeModal()','full')}`)}
async function finishTrip(n,button){const a=activeTrip();if(!a||S.busy)return;S.busy=true;button.disabled=true;button.innerHTML='<span class="spinner"></span> Saving…';
 try{await flush(5000);await api(`/api/trips/${encodeURIComponent(a.id)}/complete`,{method:'POST',body:{endOdometer:n}});S.busy=false;stopTracking();store.del('km-driver-queue');await refresh();go('historyDetail',a.id);toast('Trip completed')}
 catch(e){S.busy=false;button.disabled=false;button.textContent='Yes, complete trip';const el=document.getElementById('complete-error');if(el)el.textContent=e.message}}

function historyPage(){if(!S.data)return heading('Trip history','Loading…')+skeleton();const done=trips().filter(t=>t.status==='completed').sort((a,b)=>String(b.endedAt).localeCompare(String(a.endedAt)));
 return `${heading('Trip history','Your completed journeys, in one place.')}<div class="history-list">${done.map(h=>`<article class="order-card" role="button" tabindex="0" onclick="go('historyDetail','${esc(h.id)}')" onkeydown="if(event.key==='Enter')go('historyDetail','${esc(h.id)}')"><div class="card-top"><span class="small">${dayTime(h.endedAt)}</span>${badge('completed')}</div><h2 class="order-title">${esc(h.plate)} → ${esc(h.destination)}</h2><div class="route-numbers">${num(h.odometerDistanceKm)} <small>km · odometer</small></div><p class="small">GPS ${num(h.gpsDistanceKm)} km (approx.)</p><div class="order-bottom"><span>Estimated maintenance <b>${rp(h.estimatedMaintenanceCost)}</b>${h.estimatedMaintenanceCost==null?' · unknown':''}</span>${icon('arrow')}</div>${h.orderReference?`<p class="footnote">Order ${esc(h.orderReference)}</p>`:''}</article>`).join('')||empty('No completed trips yet.')}</div>`}
function historyDetail(){const h=trips().find(t=>t.id===S.selected);if(!h)return back('history')+empty('Trip not found');const d=S.tripDetail?.id===h.id?S.tripDetail:null,plan=h.routing?.plan,mins=h.endedAt?(Date.parse(h.endedAt)-Date.parse(h.startedAt))/60000:null;
 return `<div class="flow">${back('history')}${heading('Trip details',dayTime(h.endedAt||h.startedAt))}<div class="card" style="text-align:center"><div class="success-symbol">${icon('check')}</div><h2>${h.status==='completed'?'Trip completed':'Trip in progress'}</h2><p class="muted">${esc(h.plate)} → ${esc(h.destination)}</p></div>${mapSlot(240)}<div class="card"><h2>Distance</h2>${kv('Starting odometer',num(h.startOdometer,0)+' km')}${kv('Arrival odometer',num(h.endOdometer,0)+' km')}${kv('Odometer distance (official)',num(h.odometerDistanceKm)+' km')}${kv('GPS distance (approx.)',num(h.gpsDistanceKm)+' km')}${plan?kv('Planned route',num(plan.distanceKm)+' km'):''}</div><div class="card"><h2>Time</h2>${kv('Started',dayTime(h.startedAt))}${kv('Ended',dayTime(h.endedAt))}${kv('Duration',duration(mins))}</div><div class="card"><h2>Estimated cost</h2><div class="route-numbers">${rp(h.estimatedMaintenanceCost)}</div>${unknown(h.estimatedMaintenanceCost)}<p class="small">${h.maintenanceCpkAtStart!=null&&h.odometerDistanceKm!=null?`CPK at departure ${rp(h.maintenanceCpkAtStart)}/km × ${num(h.odometerDistanceKm)} km`:'Truck CPK was unknown at departure.'}</p><p class="footnote">Not an invoice; calculated from historical truck CPK.</p></div>${plan?`<div class="card"><h2>Selected route</h2>${kv('Provider',plan.provider==='fixture'?'sample routes':'OpenRouteService')}${kv('Route',`${num(plan.distanceKm)} km · ${duration(plan.durationMin)}`)}${kv('Recommendation',plan.cost||plan.explanation?(plan.wasRecommended?'Followed':'Different route chosen'):'None')}${plan.explanation?`<p class="footnote">${esc(plan.explanation.headline)}</p>`:''}${restrictions(plan.restrictions)}</div>`:''}<div class="card"><h2>Declaration</h2>${kv('Dimensions',`${num(h.specs.heightM)} × ${num(h.specs.widthM)} × ${num(h.specs.lengthM)} m`)}${kv('Axles',num(h.specs.axles,0))}${kv('Gross / maximum',`${num(h.specs.grossKg,0)} / ${num(h.specs.maxGrossKg,0)} kg`)}${kv('Hazardous cargo',esc((HAZMAT.find(([v])=>v===h.specs.hazmat)||[,h.specs.hazmat])[1]))}${d?'':'<p class="footnote">Loading GPS trail…</p>'}</div></div>`}

function accountPage(){const u=S.user||{},initials=esc(String(u.name||'?').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase());if(S.permission===null)checkPermission();
 return `<div class="flow">${heading('Account','Profile and app settings.')}<div class="card"><div class="profile" style="border:0;padding:0"><div class="avatar" style="width:64px;height:64px;font-size:22px">${initials}</div><div><h2>${esc(u.name)}</h2><p class="small">${esc(u.email)}</p><span class="badge blue" style="margin-top:8px">Driver</span></div></div></div><div class="card"><div class="aside-label">YOUR TRUCKS</div>${trucks().map(t=>`${kv(esc(t.plate),esc(t.model))}<p class="footnote" style="margin:0 0 12px">Odometer ${num(t.odometer,0)} km · Maintenance CPK ${cpkFor(t.id)==null?'—':rp(cpkFor(t.id))+'/km'}</p>`).join('')||'<p class="small">No trucks assigned.</p>'}</div><div class="card"><h2>App</h2>${kv('Mode','Web app (browser)')}${kv('Server',esc(location.origin))}${kv('Location permission',esc(S.permission||'unknown'))}${kv('Secure context',window.isSecureContext?'yes':'no, GPS blocked')}${kv('Map',window.maplibregl?'MapLibre + OpenStreetMap':'unavailable (offline?)')}<p class="footnote">GPS works only while this page is open. Background tracking needs a native app.</p></div>${btn(icon('logout')+' Sign out','confirmLogout()','danger full')}</div>`}
async function checkPermission(){S.permission='checking';try{const p=await navigator.permissions.query({name:'geolocation'});S.permission=p.state;p.onchange=()=>{S.permission=p.state;if(S.page==='account')render()}}catch{S.permission='unknown'}if(S.page==='account')render()}
function confirmLogout(){modal(`<h2>Sign out?</h2><p class="small">${activeTrip()?'Your active trip stays open on the server. GPS stops until you sign in again.':'You can sign in again at any time.'}</p>${btn('Yes, sign out','closeModal();signOut()','danger full')}${btn('Cancel','closeModal()','full')}`)}
function notDriverPage(){return `<div class="login-wrap"><div class="login-form"><div>${brand()}<h1>Driver accounts only</h1><p class="muted">This app is for drivers. Admins, managers and workshop staff use the web dashboard.</p>${btn('Open dashboard',"location.href='/'",'primary full')}${btn('Sign out','signOut()','full')}</div></div></div>`}

// One MapLibre instance, moved between screens.
const OSM_STYLE={version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,maxzoom:19,attribution:'© OpenStreetMap contributors'}},layers:[{id:'osm',type:'raster',source:'osm'}]};
const M={el:null,map:null,ready:false,fitKey:null};
const mapSlot=h=>`<div class="map-slot" data-map style="height:${h}px"></div>`;
const lngLat=([lat,lng])=>[lng,lat];
function mapSpec(){const p=S.page;
 if(p==='routes'&&S.preview){const routes=S.preview.routes.map((r,i)=>({coords:r.polyline,selected:i===S.routeIndex}));return {routes,trail:[],points:[{at:[S.preview.origin.latitude,S.preview.origin.longitude],kind:'origin'},...S.preview.stops.filter(s=>s.latitude!=null).map(s=>({at:[s.latitude,s.longitude],kind:'stop'}))],fitKey:'routes:'+S.preview.routing.computedAt}}
 const trip=p==='trip'?activeTrip():p==='historyDetail'?trips().find(t=>t.id===S.selected):null;if(!trip)return null;
 const d=S.tripDetail?.id===trip.id?S.tripDetail:null,trail=(d?.points||[trip.origin,trip.lastLocation].filter(Boolean)).map(x=>[x.latitude,x.longitude]);
 const here=p==='trip'&&S.tracking.last?[{at:[S.tracking.last.latitude,S.tracking.last.longitude],kind:'here'}]:[];
 return {routes:trip.routing?.plan?[{coords:trip.routing.plan.polyline,selected:true}]:[],trail,points:[{at:[trip.origin.latitude,trip.origin.longitude],kind:'origin'},...here],fitKey:'trip:'+trip.id+(d?':d':'')}}
function mountMap(){const slot=document.querySelector('[data-map]');if(!slot)return;const spec=mapSpec();
 if(!window.maplibregl||!spec){slot.innerHTML=`<div class="map-placeholder"><div class="map-grid"></div><div class="map-message">${icon('map')}<div><b>${window.maplibregl?'Map will appear when data is ready':'Map unavailable'}</b></div><p class="small">${window.maplibregl?'':'The map library could not load. Everything else still works.'}</p></div></div>`;return}
 if(!M.el){M.el=document.createElement('div');M.el.className='map-canvas';slot.appendChild(M.el);M.map=new maplibregl.Map({container:M.el,style:OSM_STYLE,center:[106.8456,-6.2088],zoom:10,attributionControl:{compact:true}});M.map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');M.map.on('load',()=>{M.ready=true;drawMap(mapSpec())})}
 else{slot.appendChild(M.el);requestAnimationFrame(()=>{M.map.resize();if(M.ready)drawMap(spec)})}}
function source(id,data){const s=M.map.getSource(id);if(s)s.setData(data);else M.map.addSource(id,{type:'geojson',data})}
function drawMap(spec){if(!spec||!M.ready)return;const map=M.map,line=(coords,props)=>({type:'Feature',properties:props,geometry:{type:'LineString',coordinates:coords.map(lngLat)}});
 source('routes',{type:'FeatureCollection',features:spec.routes.filter(r=>r.coords?.length>1).map(r=>line(r.coords,{selected:r.selected}))});
 source('trail',{type:'FeatureCollection',features:spec.trail.length>1?[line(spec.trail,{})]:[]});
 source('points',{type:'FeatureCollection',features:spec.points.map(p=>({type:'Feature',properties:{kind:p.kind},geometry:{type:'Point',coordinates:lngLat(p.at)}}))});
 if(!map.getLayer('routes-other')){
  map.addLayer({id:'routes-other',type:'line',source:'routes',filter:['==',['get','selected'],false],paint:{'line-color':'#94a3b8','line-width':4,'line-opacity':.8},layout:{'line-cap':'round','line-join':'round'}});
  map.addLayer({id:'routes-selected',type:'line',source:'routes',filter:['==',['get','selected'],true],paint:{'line-color':'#0B5FFF','line-width':6},layout:{'line-cap':'round','line-join':'round'}});
  map.addLayer({id:'trail',type:'line',source:'trail',paint:{'line-color':'#38bdf8','line-width':4}});
  map.addLayer({id:'points',type:'circle',source:'points',paint:{'circle-radius':['match',['get','kind'],'here',8,6],'circle-color':['match',['get','kind'],'origin','#0B5FFF','stop','#B45309','here','#0846BF','#111827'],'circle-stroke-color':'#fff','circle-stroke-width':2}});
 }
 if(M.fitKey!==spec.fitKey){M.fitKey=spec.fitKey;const all=[...spec.routes.flatMap(r=>r.coords||[]),...spec.trail,...spec.points.map(p=>p.at)];if(all.length){const b=new maplibregl.LngLatBounds(lngLat(all[0]),lngLat(all[0]));all.forEach(c=>b.extend(lngLat(c)));map.fitBounds(b,{padding:36,maxZoom:15,duration:0})}}}

function modal(content){document.getElementById('modal').innerHTML=`<div class="modal-overlay" onclick="if(event.target===this)closeModal()"><section class="sheet" role="dialog" aria-modal="true" aria-label="Confirmation"><button class="modal-close" aria-label="Close" onclick="closeModal()">${icon('x')}</button>${content}</section></div>`;document.querySelector('.modal-close')?.focus()}
function closeModal(){const m=document.getElementById('modal');if(m)m.innerHTML=''}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500)}
const PAGES={orders:ordersPage,detail:detailPage,trip:tripPage,pretrip:pretripPage,routes:routesPage,complete:completePage,history:historyPage,historyDetail,account:accountPage};
function render(){const app=document.getElementById('app'),p=S.page;
 if(p==='boot'){app.innerHTML=`<div class="login-wrap"><div class="login-form"><div>${brand()}<p class="muted">Loading…</p></div></div></div>`;return}
 if(p==='login'){app.innerHTML=loginPage();return}
 if(p==='notDriver'){app.innerHTML=notDriverPage();return}
 if(p==='fatal'){app.innerHTML=`<div class="login-wrap"><div class="login-form"><div>${brand()}<h1>Cannot reach the server</h1><p class="muted">${esc(S.loadError)}</p>${btn('Try again','boot()','primary full')}</div></div></div>`;return}
 app.innerHTML=shell((PAGES[p]||ordersPage)());if(p==='pretrip')updatePretrip();mountMap()}

async function boot(){S.page='boot';render();
 try{const s=await api('/api/session');S.demoMode=s.demoMode;if(!s.user){go('login');return}S.user=s.user;if(s.user.role!=='driver'){go('notDriver');return}
  await refresh();const a=activeTrip();if(a)startTracking(a.id);else{store.del('km-driver-queue');store.del('km-driver-active')}go(a?'trip':'orders')}
 catch(e){if(e.status!==401){S.loadError=e.message;S.page='fatal';render()}}}
window.addEventListener('online',()=>{render();flush()});window.addEventListener('offline',render);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&activeTrip()){keepAwake();flush();loadTripDetail()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
boot();
